namespace docking.widgets.table;








using docking;
using docking;
using ghidra.util;

public class GTableMouseListener : MouseAdapter {

	static GTableMouseListener() {
		DockingWindowManager.getHelpService().registerHelp(typeof(GTableMouseListener),
			new HelpLocation("Tables", "GhidraTableHeaders"));
	}

	private GTable table;

	private bool isDragged; // prevents popups during drag operations
	private bool isPopup; // prevents sorting during popups
	private bool sortingEnabled = true;

	GTableMouseListener(GTable table) {
		this.table = table;
	}

	void setSortingEnabled(bool enabled) {
		this.sortingEnabled = enabled;
	}

	/* @Override */
	public void mousePressed(MouseEvent e) {
		if (!e.isPopupTrigger()) {
			return;
		}

		processPopup(e);
	}

	/* @Override */
	public void mouseReleased(MouseEvent e) {
		if (!e.isPopupTrigger()) {
			isDragged = false; // allow popups to show since dragging is finished
			return;
		}

		processPopup(e);
	}

	private void processPopup(MouseEvent e) {
		if (!isDragged) {

			if (shouldIgnoreRightClick()) {
				return;
			}

			int columnIndex = table.columnAtPoint(e.getPoint());
			JPopupMenu menu = table.getTableColumnPopupMenu(columnIndex);
			if (menu != null) {
				isPopup = true;
				menu.show(e.getComponent(), e.getX(), e.getY());
			}
			e.consume();
		}
		else {
			isDragged = false; // allow popups to show since dragging is finished
		}
	}

	/* @Override */
	public void mouseClicked(MouseEvent e) {
		bool wasPopup = isPopup;
		isPopup = false;
		if (e.isConsumed() || wasPopup) {
			return;
		}

		// Map the mouse event x/y to the column selected on in the table.
		TableColumnModel colModel = table.getColumnModel();
		int colIndex = colModel.getColumnIndexAtX(e.getX());
		if (colIndex < 0) {
			return;
		}

		if (isHelpClick()) {
			DockingWindowManager.getHelpService().showHelp(getClass(), false, table);
			return;
		}

		if (!sortingEnabled) {
			return;
		}

		if (DockingUtils.isControlModifier(e)) {
			TableUtils.columnAlternativelySelected(table, colIndex);
		}
		else {
			TableUtils.columnSelected(table, colIndex);
		}

		if (colModel is GTableColumnModel) {
			// save the sort state
			((GTableColumnModel) colModel).saveState();
		}
	}

	/* @Override */
	public void mouseDragged(MouseEvent e) {
		isDragged = true;
	}

	private bool isHelpClick() {
		JTableHeader tableHeader = table.getTableHeader();
		if (!(tableHeader is GTableHeader)) {
			return false;
		}

		GTableHeader tooltipTableHeader = (GTableHeader) tableHeader;
		return tooltipTableHeader.isMouseOverHelpIcon();
	}

	private bool shouldIgnoreRightClick() {
		return isHelpClick();
	}
}
